// Descobre em qual ambiente a Kira está trabalhando com este usuário (ex.: trabalho,
// negócios, pessoal). Os ambientes ficam no campo "ambientes" do nó Ambientes da Kira;
// o escolhido fica salvo na tabela kira_config e só muda por comando ("modo ...").
const config = $('Ambientes da Kira').first().json;

function lerAmbientes(texto) {
  try {
    const lista = JSON.parse(texto || '[]');
    const validos = (Array.isArray(lista) ? lista : [])
      .filter((a) => a && a.codigo)
      .map((a) => ({ ...a, codigo: String(a.codigo).toUpperCase() }));
    if (validos.length) return validos;
  } catch (e) {
    // configuração inválida: segue com um ambiente único
  }
  return [{ codigo: 'GERAL', nome: 'Geral', descricao: '' }];
}

const ambientes = lerAmbientes(config.ambientes);
const salvo = String($input.first()?.json?.contexto ?? '').toUpperCase();
const padrao = ambientes.find((a) => a.codigo === String(config.ambiente_padrao || '').toUpperCase()) ?? ambientes[0];
const atual = ambientes.find((a) => a.codigo === salvo) ?? padrao;

return [
  {
    json: {
      ambiente: atual.codigo,
      ambiente_nome: atual.nome || atual.codigo,
      ambiente_descricao: atual.descricao || '',
      ambientes_texto: ambientes.map((a) => `- ${a.codigo} (${a.nome || a.codigo}): ${a.descricao || ''}`.trim()).join('\n'),
    },
  },
];

