// Monta a resposta dos comandos (/start, /ajuda, /status, /memorias, /limpar, /id, /publicar).
// O texto segue para "Resposta pronta", que cuida da formatação e do envio.
const entrada = $('Normalizar entrada').first().json;
const config = $('Configuração da Kira').first().json;
const ambiente = $('Ambiente atual').first().json;

// Memórias do ambiente ativo e as gerais (as antigas, sem ambiente, usam a categoria).
function lerAmbientes(texto) {
  try {
    const lista = JSON.parse(texto || '[]');
    return (Array.isArray(lista) ? lista : []).filter((a) => a && a.codigo);
  } catch (e) {
    return [];
  }
}
const normalizar = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .trim();
const ambientes = lerAmbientes($('Ambientes da Kira').first().json.ambientes);
const apelidos = {};
for (const a of ambientes) {
  for (const n of [a.codigo, a.nome, ...(a.apelidos || [])]) apelidos[normalizar(n)] = String(a.codigo).toUpperCase();
}
const ambienteDa = (m) => String(m.contexto || apelidos[normalizar(m.categoria)] || 'GERAL').toUpperCase();
const memorias = $input
  .all()
  .map((item) => item.json)
  .filter((m) => m && m.fato)
  .map((m) => ({ ...m, ambiente: ambienteDa(m) }))
  .filter((m) => m.ambiente === ambiente.ambiente || m.ambiente === 'GERAL');
const nomesDosAmbientes = ambientes.map((a) => a.nome || a.codigo);

const nome = config.nome_dono || entrada.nome_usuario || '';
const agora = DateTime.now()
  .setZone(config.fuso_horario || 'America/Sao_Paulo')
  .setLocale('pt-BR')
  .toFormat("dd/MM/yyyy 'às' HH:mm");

const modosDeVoz = {
  espelho: 'quando você manda áudio, eu respondo em áudio',
  sempre: 'eu sempre respondo em áudio',
  nunca: 'eu respondo sempre por texto',
};

const listaDeComandos = [
  '/ajuda — mostra esta lista',
  '/status — mostra se estou online e como estou configurada',
  '/memorias — mostra o que eu guardei sobre você',
  '/limpar — apaga o histórico recente da conversa (as memórias continuam)',
  '/id — mostra o seu ID do Telegram',
  ...(nomesDosAmbientes.length ? [`modo <ambiente> — troca de ambiente (${nomesDosAmbientes.join(', ')})`] : []),
  '/publicar N — publica no LinkedIn o rascunho N que eu preparei (com a imagem, se tiver)',
].join('\n');

// Resultado do /publicar N: o post só vai para o LinkedIn por este comando.
function resultadoDoPublicar() {
  const numero = String(entrada.texto || '').trim().split(/\s+/)[1] || '';
  const executou = (no) => {
    try {
      return Boolean($(no).isExecuted);
    } catch (e) {
      return false;
    }
  };
  const erroDe = (no) => {
    try {
      const falha = $(no).all(1)?.[0]?.json?.error;
      return typeof falha === 'string' ? falha : (falha?.message ?? '');
    } catch (e) {
      return '';
    }
  };
  if (!numero) return 'Me diga qual rascunho publicar, por exemplo: /publicar 3';
  const rascunho = executou('Buscar rascunho (LinkedIn)') ? ($('Buscar rascunho (LinkedIn)').first()?.json ?? {}) : {};
  if (!rascunho.texto) return `Não encontrei o rascunho ${numero} pendente. Peça para eu escrever o post de novo.`;
  const imagem = Number(rascunho.imagem_id) || 0;
  if (executou('Marcar como publicado')) {
    return `✅ Publiquei no LinkedIn o rascunho ${numero}${imagem ? ` com a imagem #${imagem}` : ''}.`;
  }
  if (imagem && !executou('Publicar no LinkedIn (com imagem)')) {
    const erro = erroDe('Baixar imagem (LinkedIn)');
    return `😕 Não consegui pegar a imagem #${imagem} do rascunho ${numero}.${erro ? ` Erro: ${erro}` : ''} Nada foi publicado; o rascunho continua guardado.`;
  }
  const erro = erroDe(imagem ? 'Publicar no LinkedIn (com imagem)' : 'Publicar no LinkedIn');
  return `😕 Não consegui publicar o rascunho ${numero} no LinkedIn.${erro ? ` Erro: ${erro}` : ''} O rascunho continua guardado.`;
}

let texto;
switch (entrada.comando) {
  case '/start':
    texto = [
      `Olá, ${nome}! Eu sou a **Kira** 👋`,
      'Sua assistente pessoal, rodando no seu próprio servidor.',
      '',
      'Pode falar comigo por **texto**, mandar um **áudio** 🎙️ ou uma **foto** 📷 — quando você fala, eu respondo falando.',
      '',
      'Digite /ajuda para ver os comandos.',
    ].join('\n');
    break;
  case '/ajuda':
  case '/help':
  case '/comandos':
    texto = `**Comandos da Kira**\n\n${listaDeComandos}\n\nFora isso, é só conversar comigo por texto, áudio ou foto. Também consulto seus e-mails, agenda e Google Drive, preparo rascunhos de resposta no Outlook e posts para o LinkedIn, gero imagens, entendo e edito as suas fotos, pesquiso na internet, consulto os pedidos da base oficial e o Power BI da empresa no modo Trabalho, consulto a planilha do negócio no modo Negócios e leio e respondo no Teams quando você pede. Nada é enviado ou publicado sem você pedir. 🙂`;
    break;
  case '/status':
    texto = [
      '✅ **Kira 1.0 online**',
      `🕒 ${agora}`,
      `🗂️ Ambiente: ${ambiente.ambiente_nome}`,
      '🧠 Cérebro: Google Gemini',
      '📬 Outlook: e-mails e agenda (leitura) e rascunhos de resposta',
      '📁 Google Drive: leitura',
      '💼 LinkedIn: rascunhos, com ou sem imagem (publica só com /publicar)',
      '🖼️ Imagens: entendo suas fotos, gero e edito com o Gemini e mando aqui',
      '💬 Teams: leio e respondo quando você pede',
      '📦 Pedidos: consulto a base oficial de pedidos (ERP), atualizada de seg a sáb às 9h, 12h, 15h e 18h',
      '📊 Power BI: consulto os modelos e relatórios da empresa (só leitura, no modo Trabalho)',
      '💎 Negócio: consulto a planilha do negócio no Google Drive (só no modo Negócios)',
      '🌐 Internet: pesquiso no Google quando preciso de informação atualizada',
      `🎙️ Voz: ${modosDeVoz[config.modo_voz] || config.modo_voz}`,
      `📌 Memórias guardadas: ${memorias.length}`,
    ].join('\n');
    break;
  case '/memorias':
  case '/memoria':
    texto = memorias.length
      ? [
          `📌 **O que eu guardei sobre você** — ambiente ${ambiente.ambiente_nome} e gerais (${memorias.length})`,
          '',
          ...memorias.map((m) => `- [${m.id}] (${m.ambiente}${m.contexto && m.categoria ? ` · ${m.categoria}` : ''}) ${m.fato}`),
          '',
          'Para eu esquecer algo, é só pedir: "Kira, esqueça a memória 3".',
        ].join('\n')
      : `Ainda não guardei nenhuma memória no ambiente ${ambiente.ambiente_nome}. É só pedir: "Kira, lembre que..." 🙂`;
    break;
  case '/limpar':
  case '/reset':
    texto = `🧹 Pronto! Apaguei o histórico recente da nossa conversa no ambiente ${ambiente.ambiente_nome}. As memórias guardadas continuam (veja em /memorias).`;
    break;
  case '/publicar':
    texto = resultadoDoPublicar();
    break;
  case '/id':
    texto = `🆔 Seu ID do Telegram: \`${entrada.user_id}\`\nID deste chat: \`${entrada.chat_id}\``;
    break;
  default:
    texto = `Não conheço o comando ${entrada.comando}. Digite /ajuda para ver o que eu sei fazer.`;
}

return [
  {
    json: {
      texto_resposta: texto,
      modo_resposta: 'texto',
      status: 'comando',
      erro: '',
      entrada: entrada.texto,
    },
  },
];

// Recebe a resposta de qualquer caminho (conversa, comando, erro, acesso negado...)
// e decide se ela vai por voz ou por texto. Também prepara o texto que será falado
// e a legenda do áudio.
const envelope = $input.first().json;
const entrada = $('Normalizar entrada').first().json;
const config = $('Configuração da Kira').first().json;

const texto =
  String(envelope.texto_resposta ?? '').trim() ||
  'Desculpe, não consegui formular uma resposta agora. Pode repetir?';

// Tira a marcação Markdown e mantém o conteúdo.
function semMarkdown(s) {
  return s
    .replace(/```[\w+-]*\n?([\s\S]*?)```/g, '$1')
    .replace(/`([^`\n]+)`/g, '$1')
    .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1 ($2)')
    .replace(/^[ \t]*#{1,6}[ \t]+/gm, '')
    .replace(/^([ \t]*)[*+-][ \t]+/gm, '$1• ')
    .replace(/\*\*|__|~~/g, '')
    .replace(/(^|[^\w*])\*(?=\S)([^*\n]*?\S)\*(?![\w*])/g, '$1$2')
    .replace(/(^|[^\w])_(?=\S)([^_\n]*?\S)_(?!\w)/g, '$1$2')
    .trim();
}

// Texto que vai virar áudio: sem links, emojis e marcadores de lista.
function paraFala(s) {
  return semMarkdown(s)
    .replace(/\s*\(?https?:\/\/\S+/g, '')
    .replace(/[\p{Extended_Pictographic}\u{1F1E6}-\u{1F1FF}\u{FE0F}\u{200D}\u{20E3}]/gu, '')
    .replace(/^[ \t]*•[ \t]*/gm, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n+ */g, '\n')
    .trim();
}

const escapar = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const pediuVoz = envelope.modo_resposta === 'voz';
const textoFala = paraFala(texto);
const limiteVoz = Number(config.max_caracteres_voz) || 1500;
const falar = pediuVoz && textoFala.length > 0 && textoFala.length <= limiteVoz;

// Legenda do áudio (o Telegram aceita até 1024 caracteres).
const caracteres = Array.from(semMarkdown(texto));
const legenda = escapar(
  caracteres.length > 900 ? caracteres.slice(0, 897).join('').trimEnd() + '…' : caracteres.join(''),
);

const avisos = [envelope.erro];
if (pediuVoz && !falar) avisos.push('resposta longa demais para voz: enviada como texto');

return [
  {
    json: {
      chat_id: entrada.chat_id,
      texto,
      modo_resposta: falar ? 'voz' : 'texto',
      texto_fala: textoFala,
      legenda,
      voz_tts: config.voz_tts || 'Kore',
      status: envelope.status || 'ok',
      erro: avisos.filter(Boolean).join(' | '),
      entrada: envelope.entrada ?? entrada.texto ?? '',
    },
  },
];

// Troca de ambiente por comando: "modo negócios", "/pessoal", "/modo trabalho",
// "Kira, mude para o ambiente pessoal", "quero o modo pessoal". Só vale para mensagens
// curtas, para não confundir com uma conversa normal. Nos áudios, a transcrição às vezes
// escreve "moto" no lugar de "modo" e "Akira" ou "Okira" no lugar de "Kira".
const config = $('Ambientes da Kira').first().json;
const pergunta = String($('Pergunta').first().json.pergunta ?? '');

function lerAmbientes(texto) {
  try {
    const lista = JSON.parse(texto || '[]');
    const validos = (Array.isArray(lista) ? lista : [])
      .filter((a) => a && a.codigo)
      .map((a) => ({ ...a, codigo: String(a.codigo).toUpperCase() }));
    if (validos.length) return validos;
  } catch (e) {
    // configuração inválida: sem troca de ambiente
  }
  return [];
}

const normalizar = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9/ ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const texto = normalizar(pergunta)
  .replace(/^((ok|oi|ola|ei|o|a) )?(kira|akira|okira) /, '')
  .replace(/ (por favor|agora|ai|ta|ok)$/, '');
const desejo = '((eu )?(quero|queria|vou|vamos|pode|preciso) )?';
const verbos = '(mude|muda|mudar|troque|troca|trocar|va|vai|ir|vamos|passe|passa|passar|entre|entra|entrar|ative|ativa|ativar|use|usa|usar|coloque|coloca|colocar|volte|volta|voltar|abra|abre|abrir)';
const modo = '(modo|moto|ambiente)';

let escolhido = null;
if (texto.length <= 60) {
  for (const ambiente of lerAmbientes(config.ambientes)) {
    const nomes = [ambiente.codigo, ambiente.nome, ...(ambiente.apelidos || [])].map(normalizar).filter(Boolean);
    const pediu = nomes.some((nome) =>
      [
        `^/${nome}$`,
        `^/?modo ${nome}$`,
        `^${desejo}(o )?${modo} ${nome}$`,
        `^${desejo}${verbos}( para| pro| pra| no| na| em)?( o| a)? ${modo} ${nome}$`,
        `^${desejo}${verbos}( para| pro| pra)( o| a)? ${nome}$`,
      ].some((padrao) => new RegExp(padrao).test(texto)),
    );
    if (pediu) {
      escolhido = ambiente;
      break;
    }
  }
}

return [
  {
    json: {
      troca: escolhido ? escolhido.codigo : '',
      ambiente_nome: escolhido ? escolhido.nome || escolhido.codigo : '',
      ambiente_descricao: escolhido ? escolhido.descricao || '' : '',
    },
  },
];

// Separa as memórias por ambiente: a Kira só vê as do ambiente ativo e as gerais (GERAL).
// Memórias antigas, sem ambiente, usam a categoria para descobrir a qual ambiente pertencem.
const config = $('Ambientes da Kira').first().json;
const atual = $('Ambiente atual').first().json.ambiente;

function lerAmbientes(texto) {
  try {
    const lista = JSON.parse(texto || '[]');
    return (Array.isArray(lista) ? lista : []).filter((a) => a && a.codigo);
  } catch (e) {
    return [];
  }
}

const normalizar = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .trim();

const apelidos = {};
for (const ambiente of lerAmbientes(config.ambientes)) {
  for (const nome of [ambiente.codigo, ambiente.nome, ...(ambiente.apelidos || [])]) {
    apelidos[normalizar(nome)] = String(ambiente.codigo).toUpperCase();
  }
}
const ambienteDa = (m) => String(m.contexto || apelidos[normalizar(m.categoria)] || 'GERAL').toUpperCase();

const memorias = $input
  .all()
  .map((item) => item.json)
  .filter((m) => m && m.fato)
  .map((m) => ({ ...m, ambiente: ambienteDa(m) }))
  .filter((m) => m.ambiente === atual || m.ambiente === 'GERAL');

const texto =
  memorias
    .map((m) => `[${m.id}] (${m.ambiente}${m.contexto && m.categoria ? ` · ${m.categoria}` : ''}) ${m.fato}`)
    .join('\n') || '(nenhuma memória guardada neste ambiente ainda)';

return [{ json: { memorias: texto, total: memorias.length } }];

// O histórico da conversa quebrou (o Gemini recusou o pedido) e vai ser reiniciado. Para a Kira não perder
// o fio, o histórico novo começa com um resumo das últimas trocas deste chat neste ambiente (tabela kira_logs).
const corta = (texto, maximo) => {
  const t = String(texto ?? '').replace(/\s+/g, ' ').trim();
  return t.length > maximo ? t.slice(0, maximo - 1) + '…' : t;
};
const trocas = $input
  .all()
  .map((item) => item.json)
  .filter((linha) => linha.entrada && linha.resposta && linha.tipo_entrada !== 'comando')
  .reverse()
  .map((linha) => `Ele: ${corta(linha.entrada, 400)}\nVocê: ${corta(linha.resposta, 600)}`);

const resumo = trocas.length
  ? 'Contexto: o histórico desta conversa foi reiniciado. Estas foram as últimas mensagens, da mais antiga para a mais recente:\n\n' + trocas.join('\n\n')
  : 'Contexto: o histórico desta conversa foi reiniciado e não há mensagens anteriores.';
return [{ json: { resumo, trocas: trocas.length } }];

// Com o histórico reiniciado, a mesma pergunta volta para a Kira (uma vez só: "Histórico quebrado?" só repete
// na primeira falha).
return $('Contexto da conversa').all().map((item) => ({ json: item.json }));

// Pega o áudio devolvido pelo Gemini (voz) e entrega um arquivo WAV para o Telegram.
// Os modelos de voz do Gemini devolvem WAV pronto ou áudio "cru" (PCM 16 bits, mono);
// no segundo caso, este nó acrescenta o cabeçalho WAV.
const resposta = $input.first().json;
const partes = resposta.candidates?.[0]?.content?.parts ?? [];
const audio = partes.find((p) => p.inlineData?.data)?.inlineData;
if (!audio) {
  throw new Error('O Gemini não devolveu áudio: ' + JSON.stringify(resposta).slice(0, 300));
}

const bytes = Buffer.from(audio.data, 'base64');
const jaEhWav = bytes.subarray(0, 4).toString('ascii') === 'RIFF';

let wav = bytes;
const taxa = Number((String(audio.mimeType).match(/rate=(\d+)/) || [])[1]) || 24000;
let bytesPorSegundo = taxa * 2;
let tamanhoAudio = bytes.length;

if (jaEhWav) {
  // Lê a taxa do próprio cabeçalho e o tamanho do bloco de áudio ("data").
  bytesPorSegundo = bytes.readUInt32LE(28) || bytesPorSegundo;
  let i = 12;
  while (i + 8 <= bytes.length) {
    const bloco = bytes.subarray(i, i + 4).toString('ascii');
    const tamanho = bytes.readUInt32LE(i + 4);
    if (bloco === 'data') {
      tamanhoAudio = tamanho;
      break;
    }
    i += 8 + tamanho + (tamanho % 2);
  }
} else {
  const cabecalho = Buffer.alloc(44);
  cabecalho.write('RIFF', 0);
  cabecalho.writeUInt32LE(36 + bytes.length, 4);
  cabecalho.write('WAVE', 8);
  cabecalho.write('fmt ', 12);
  cabecalho.writeUInt32LE(16, 16); // tamanho do bloco "fmt "
  cabecalho.writeUInt16LE(1, 20); // PCM
  cabecalho.writeUInt16LE(1, 22); // mono
  cabecalho.writeUInt32LE(taxa, 24);
  cabecalho.writeUInt32LE(bytesPorSegundo, 28);
  cabecalho.writeUInt16LE(2, 32); // bytes por amostra
  cabecalho.writeUInt16LE(16, 34); // bits por amostra
  cabecalho.write('data', 36);
  cabecalho.writeUInt32LE(bytes.length, 40);
  wav = Buffer.concat([cabecalho, bytes]);
}

return [
  {
    json: {
      audioContent: wav.toString('base64'),
      segundos: Math.max(1, Math.round(tamanhoAudio / bytesPorSegundo)),
    },
  },
];

// Converte a resposta (Markdown simples) para o HTML aceito pelo Telegram e divide
// textos longos em partes (o Telegram aceita até 4096 caracteres por mensagem).
const resposta = $('Resposta pronta').first().json;
const LIMITE = 3500;

const escapar = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function markdownParaHtml(md) {
  // Código e links são convertidos antes e guardados, para não serem alterados depois.
  const guardados = [];
  const guardar = (html) => `\u0000${guardados.push(html) - 1}\u0000`;
  const t = md
    .replace(/```[\w+-]*\n?([\s\S]*?)```/g, (_, codigo) =>
      guardar(`<pre>${escapar(codigo.replace(/\n$/, ''))}</pre>`),
    )
    .replace(/`([^`\n]+)`/g, (_, codigo) => guardar(`<code>${escapar(codigo)}</code>`))
    .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g, (_, rotulo, url) =>
      guardar(`<a href="${escapar(url).replace(/"/g, '&quot;')}">${escapar(rotulo)}</a>`),
    );
  return escapar(t)
    .replace(/^[ \t]*#{1,6}[ \t]+(.+?)[ \t#]*$/gm, (_, titulo) => `<b>${titulo.replace(/\*\*|__/g, '')}</b>`)
    .replace(/^([ \t]*)[*+-][ \t]+/gm, '$1• ')
    .replace(/\*\*(?=\S)([^\n]*?\S)\*\*/g, '<b>$1</b>')
    .replace(/__(?=\S)([^\n]*?\S)__/g, '<b>$1</b>')
    .replace(/(^|[^\w*])\*(?=\S)([^*\n]*?\S)\*(?![\w*])/g, '$1<i>$2</i>')
    .replace(/(^|[^\w])_(?=\S)([^_\n]*?\S)_(?!\w)/g, '$1<i>$2</i>')
    .replace(/~~(?=\S)([^~\n]*?\S)~~/g, '<s>$1</s>')
    .replace(/\u0000(\d+)\u0000/g, (_, i) => guardados[Number(i)]);
}

function dividir(texto, limite) {
  const partes = [];
  let resto = texto;
  while (resto.length > limite) {
    let corte = resto.lastIndexOf('\n\n', limite);
    if (corte < limite / 2) corte = resto.lastIndexOf('\n', limite);
    if (corte < limite / 2) corte = resto.lastIndexOf(' ', limite);
    if (corte < limite / 2) corte = limite;
    partes.push(resto.slice(0, corte).trim());
    resto = resto.slice(corte).trim();
  }
  if (resto) partes.push(resto);
  return partes;
}

return dividir(resposta.texto || '…', LIMITE).map((parte) => ({
  json: {
    html: markdownParaHtml(parte),
    texto_simples: escapar(parte),
  },
}));
